### Example 1: Basic Single Inheritance
```python
class Animal:
    def __init__(self, name, species):
        self.name = name
        self.species = species

    def make_sound(self):
        return "Some animal sound"

    def get_info(self):
        return f"{self.name} is a {self.species}"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name, "Dog")
        self.breed = breed

    def make_sound(self):
        return "Woof! Woof!"

    def fetch(self):
        return f"{self.name} is fetching the ball"

# Creating objects
my_dog = Dog("Buddy", "Golden Retriever")
print(my_dog.get_info())    # Inherited method
print(my_dog.make_sound())  # Overridden method
print(my_dog.fetch())       # New method
```

### Example 2: Employee Hierarchy
```python
class Employee:
    def __init__(self, name, employee_id, salary):
        self.name = name
        self.employee_id = employee_id
        self.salary = salary

    def get_info(self):
        return f"ID: {self.employee_id}, Name: {self.name}, Salary: ${self.salary}"

    def calculate_bonus(self):
        return self.salary * 0.1  # 10% bonus

class Manager(Employee):
    def __init__(self, name, employee_id, salary, department):
        super().__init__(name, employee_id, salary)
        self.department = department
        self.subordinates = []

    def add_subordinate(self, employee):
        self.subordinates.append(employee)
        return f"Added {employee.name} to {self.department}"

    def calculate_bonus(self):
        base_bonus = super().calculate_bonus()
        management_bonus = len(self.subordinates) * 100
        return base_bonus + management_bonus

    def get_info(self):
        base_info = super().get_info()
        return f"{base_info}, Department: {self.department}, Subordinates: {len(self.subordinates)}"

class Developer(Employee):
    def __init__(self, name, employee_id, salary, programming_language):
        super().__init__(name, employee_id, salary)
        self.programming_language = programming_language
        self.projects = []

    def add_project(self, project):
        self.projects.append(project)
        return f"Added {project} to {self.name}'s projects"

    def calculate_bonus(self):
        base_bonus = super().calculate_bonus()
        project_bonus = len(self.projects) * 50
        return base_bonus + project_bonus

# Creating objects
manager = Manager("John Smith", "M001", 80000, "Engineering")
dev1 = Developer("Alice Johnson", "D001", 70000, "Python")
dev2 = Developer("Bob Wilson", "D002", 75000, "Java")

manager.add_subordinate(dev1)
manager.add_subordinate(dev2)

print(manager.get_info())
print(f"Manager bonus: ${manager.calculate_bonus()}")
print(dev1.get_info())
```

### Example 3: Multiple Inheritance
```python
class Flyable:
    def __init__(self):
        self.altitude = 0

    def fly(self):
        self.altitude += 1000
        return f"Flying at {self.altitude} feet"

    def land(self):
        self.altitude = 0
        return "Landed safely"

class Swimmable:
    def __init__(self):
        self.depth = 0

    def swim(self):
        self.depth += 10
        return f"Swimming at {self.depth} meters"

    def dive(self):
        self.depth += 50
        return f"Diving to {self.depth} meters"

class Duck(Flyable, Swimmable):
    def __init__(self, name):
        Flyable.__init__(self)
        Swimmable.__init__(self)
        self.name = name

    def quack(self):
        return f"{self.name} says Quack!"

    def get_status(self):
        return f"{self.name} - Altitude: {self.altitude}ft, Depth: {self.depth}m"

# Creating duck object
donald = Duck("Donald")
print(donald.quack())
print(donald.fly())
print(donald.swim())
print(donald.get_status())
```

### Example 4: Method Resolution Order (MRO)
```python
class A:
    def method(self):
        return "A"

class B(A):
    def method(self):
        return "B"

class C(A):
    def method(self):
        return "C"

class D(B, C):
    def method(self):
        return "D"

# Understanding MRO
print("Method Resolution Order for class D:")
print(D.__mro__)

# Creating object and testing method calls
obj = D()
print(obj.method())  # Calls D's method

# Using super() to call parent methods
class E(B, C):
    def method(self):
        return f"E -> {super().method()}"

obj_e = E()
print(obj_e.method())  # Calls B's method (first in MRO)
```

### Example 5: Real-world Banking System
```python
class Account:
    def __init__(self, account_number, holder_name, balance=0):
        self.account_number = account_number
        self.holder_name = holder_name
        self.balance = balance
        self.transactions = []

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transactions.append(f"Deposit: +${amount}")
            return f"Deposited ${amount}. Balance: ${self.balance}"
        return "Invalid amount"

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            self.transactions.append(f"Withdrawal: -${amount}")
            return f"Withdrew ${amount}. Balance: ${self.balance}"
        return "Insufficient funds"

    def get_balance(self):
        return self.balance

class SavingsAccount(Account):
    def __init__(self, account_number, holder_name, balance=0, interest_rate=0.02):
        super().__init__(account_number, holder_name, balance)
        self.interest_rate = interest_rate

    def add_interest(self):
        interest = self.balance * self.interest_rate
        self.balance += interest
        self.transactions.append(f"Interest: +${interest:.2f}")
        return f"Added interest: ${interest:.2f}. New balance: ${self.balance:.2f}"

    def withdraw(self, amount):
        if self.balance - amount < 100:  # Minimum balance requirement
            return "Cannot withdraw: Minimum balance requirement not met"
        return super().withdraw(amount)

class CheckingAccount(Account):
    def __init__(self, account_number, holder_name, balance=0, overdraft_limit=500):
        super().__init__(account_number, holder_name, balance)
        self.overdraft_limit = overdraft_limit

    def withdraw(self, amount):
        if amount <= self.balance + self.overdraft_limit:
            self.balance -= amount
            self.transactions.append(f"Withdrawal: -${amount}")
            return f"Withdrew ${amount}. Balance: ${self.balance}"
        return "Exceeds overdraft limit"

# Creating different account types
savings = SavingsAccount("SA001", "John Doe", 1000)
checking = CheckingAccount("CA001", "Jane Smith", 500)

print(savings.deposit(500))
print(savings.add_interest())
print(savings.withdraw(200))
print(savings.withdraw(1500))  # Should fail due to minimum balance

print(checking.withdraw(800))  # Should work due to overdraft
print(checking.deposit(300))
```

### Example 6: Vehicle Hierarchy
```python
class Vehicle:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year
        self.is_running = False

    def start_engine(self):
        self.is_running = True
        return f"{self.make} {self.model} engine started"

    def stop_engine(self):
        self.is_running = False
        return f"{self.make} {self.model} engine stopped"

    def get_info(self):
        return f"{self.year} {self.make} {self.model}"

class Car(Vehicle):
    def __init__(self, make, model, year, num_doors):
        super().__init__(make, model, year)
        self.num_doors = num_doors
        self.fuel_level = 100

    def refuel(self, amount):
        self.fuel_level = min(100, self.fuel_level + amount)
        return f"Fuel level: {self.fuel_level}%"

    def get_info(self):
        base_info = super().get_info()
        return f"{base_info} - {self.num_doors} doors"

class Motorcycle(Vehicle):
    def __init__(self, make, model, year, engine_size):
        super().__init__(make, model, year)
        self.engine_size = engine_size
        self.has_sidecar = False

    def attach_sidecar(self):
        self.has_sidecar = True
        return "Sidecar attached"

    def detach_sidecar(self):
        self.has_sidecar = False
        return "Sidecar detached"

    def get_info(self):
        base_info = super().get_info()
        return f"{base_info} - {self.engine_size}cc engine"

class ElectricVehicle(Vehicle):
    def __init__(self, make, model, year, battery_capacity):
        super().__init__(make, model, year)
        self.battery_capacity = battery_capacity
        self.charge_level = 100

    def charge(self, amount):
        self.charge_level = min(100, self.charge_level + amount)
        return f"Charge level: {self.charge_level}%"

    def start_engine(self):
        if self.charge_level > 0:
            return super().start_engine()
        return "Cannot start: Battery empty"

# Creating vehicle objects
car = Car("Toyota", "Camry", 2020, 4)
motorcycle = Motorcycle("Honda", "CBR600", 2019, 600)
ev = ElectricVehicle("Tesla", "Model 3", 2021, 75)

print(car.get_info())
print(car.start_engine())
print(car.refuel(20))

print(motorcycle.get_info())
print(motorcycle.attach_sidecar())

print(ev.get_info())
print(ev.charge(30))
```
